<?php
declare(strict_types=1);
$root=dirname(__DIR__,2);
$plan=file_get_contents($root.'/packaging/releases/0.10.0-assets.json');
$source=file_get_contents(__DIR__.'/publish-release.php');
$bootstrap= <<<'SH'
#!/bin/sh
# Generated by render-publisher.php. Run after gh auth login. No Python/build.
set -eu
ASYNCARA_PUBLISH_SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
export ASYNCARA_PUBLISH_SCRIPT_DIR
exec "${ASYNCARA_PHP:-php}" -n /dev/stdin "$@" <<'ASYNCARA_PUBLISH_PHP'
SH;
$php="<?php\ndeclare(strict_types=1);\nconst ASYNCARA_PUBLICATION_PLAN = <<<'ASYNCARA_ASSET_PLAN'\n".$plan."ASYNCARA_ASSET_PLAN;\n";
$source=preg_replace('/\A<\?php\s*declare\(strict_types=1\);\s*/','',$source,1);
$script=$bootstrap."\n".$php.$source."ASYNCARA_PUBLISH_PHP\n";
$path=__DIR__.'/publish-0.10.0.sh';
if(in_array('--check',$argv,true)) { if(file_get_contents($path)!==$script) throw new RuntimeException('Regenerate publish-0.10.0.sh'); }
else { file_put_contents($path,$script); chmod($path,0755); }
